"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[31532],{20171(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>n,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/cleancode/modulos/proyecto-final-entrevista/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el \\"CRAP Index\\" (Change Risk Analysis and Predictions) y por qu\xe9 combina complejidad ciclom\xe1tica con cobertura de tests? \xbfPor qu\xe9 es una m\xe9trica m\xe1s predictiva de riesgo de cambio que la complejidad ciclom\xe1tica sola?","source":"@site/docs/cursos/cleancode/modulos/10-proyecto-final-entrevista/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/10-proyecto-final-entrevista","slug":"/cursos/cleancode/modulos/proyecto-final-entrevista/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/proyecto-final-entrevista/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/proyecto-final-entrevista/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/proyecto-final-entrevista/ejercicio"}}');var i=o(74848),r=o(28453);const n={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 es el &quot;CRAP Index&quot; (Change Risk Analysis and Predictions) y por qu\xe9 combina complejidad ciclom\xe1tica con cobertura de tests? \xbfPor qu\xe9 es una m\xe9trica m\xe1s predictiva de riesgo de cambio que la complejidad ciclom\xe1tica sola?",id:"2-investigar-qu\xe9-es-el-crap-index-change-risk-analysis-and-predictions-y-por-qu\xe9-combina-complejidad-ciclom\xe1tica-con-cobertura-de-tests-por-qu\xe9-es-una-m\xe9trica-m\xe1s-predictiva-de-riesgo-de-cambio-que-la-complejidad-ciclom\xe1tica-sola",level:3},{value:"3. [Investigar] \xbfQu\xe9 es el &quot;rewrite trap&quot; del que advierte Joel Spolsky y por qu\xe9 es relevante para el proyecto final de refactorizaci\xf3n? \xbfQu\xe9 argumenta Spolsky que es preferible a reescribir un sistema legacy?",id:"3-investigar-qu\xe9-es-el-rewrite-trap-del-que-advierte-joel-spolsky-y-por-qu\xe9-es-relevante-para-el-proyecto-final-de-refactorizaci\xf3n-qu\xe9-argumenta-spolsky-que-es-preferible-a-reescribir-un-sistema-legacy",level:3},{value:"4. [Investigar] \xbfQu\xe9 es el &quot;Bus Factor&quot; (o &quot;Lottery Factor&quot;) y c\xf3mo las pr\xe1cticas de Clean Code lo mitigan? \xbfQu\xe9 estudios cuantitativos existen sobre la relaci\xf3n entre legibilidad de c\xf3digo y la capacidad de incorporar nuevos desarrolladores al equipo?",id:"4-investigar-qu\xe9-es-el-bus-factor-o-lottery-factor-y-c\xf3mo-las-pr\xe1cticas-de-clean-code-lo-mitigan-qu\xe9-estudios-cuantitativos-existen-sobre-la-relaci\xf3n-entre-legibilidad-de-c\xf3digo-y-la-capacidad-de-incorporar-nuevos-desarrolladores-al-equipo",level:3},{value:"5. [Conectar] La clase presenta una r\xfabrica de evaluaci\xf3n con categor\xedas (Nombres, Funciones, Tests, etc.). \xbfC\xf3mo se relaciona esta r\xfabrica con los niveles de &quot;Software Maintainability Index&quot; (MI) definidos en el est\xe1ndar ISO/IEC 25010? \xbfQu\xe9 mide el MI que la r\xfabrica de la clase no captura?",id:"5-conectar-la-clase-presenta-una-r\xfabrica-de-evaluaci\xf3n-con-categor\xedas-nombres-funciones-tests-etc-c\xf3mo-se-relaciona-esta-r\xfabrica-con-los-niveles-de-software-maintainability-index-mi-definidos-en-el-est\xe1ndar-isoiec-25010-qu\xe9-mide-el-mi-que-la-r\xfabrica-de-la-clase-no-captura",level:3},{value:"6. [Conectar] La clase estructura la entrevista t\xe9cnica con 10 ejercicios pr\xe1cticos y 50 preguntas te\xf3ricas. \xbfQu\xe9 es el m\xe9todo STAR (Situation, Task, Action, Result) para entrevistas de comportamiento y c\xf3mo se aplica para responder preguntas sobre experiencia con Clean Code que van m\xe1s all\xe1 de las respuestas t\xe9cnicas?",id:"6-conectar-la-clase-estructura-la-entrevista-t\xe9cnica-con-10-ejercicios-pr\xe1cticos-y-50-preguntas-te\xf3ricas-qu\xe9-es-el-m\xe9todo-star-situation-task-action-result-para-entrevistas-de-comportamiento-y-c\xf3mo-se-aplica-para-responder-preguntas-sobre-experiencia-con-clean-code-que-van-m\xe1s-all\xe1-de-las-respuestas-t\xe9cnicas",level:3},{value:"7. [Conectar] La clase pide cobertura &gt; 80% como requisito del proyecto final. \xbfQu\xe9 dice la investigaci\xf3n de Inozemtseva y Holmes (2014, ICSE) sobre la correlaci\xf3n entre cobertura de tests y defectos post-release? \xbfPor qu\xe9 &quot;coverage is not a good measure of test suite quality&quot; seg\xfan este estudio?",id:"7-conectar-la-clase-pide-cobertura--80-como-requisito-del-proyecto-final-qu\xe9-dice-la-investigaci\xf3n-de-inozemtseva-y-holmes-2014-icse-sobre-la-correlaci\xf3n-entre-cobertura-de-tests-y-defectos-post-release-por-qu\xe9-coverage-is-not-a-good-measure-of-test-suite-quality-seg\xfan-este-estudio",level:3},{value:"8. [Cuestionar] La clase eval\xfaa el proyecto con una r\xfabrica que asigna pesos a cada categor\xeda. \xbfQu\xe9 implicancias tiene pesar Tests 25% y Comentarios 5%? \xbfRefleja esto las prioridades correctas seg\xfan la investigaci\xf3n emp\xedrica de defectos, o es una valoraci\xf3n subjetiva de Robert C. Martin?",id:"8-cuestionar-la-clase-eval\xfaa-el-proyecto-con-una-r\xfabrica-que-asigna-pesos-a-cada-categor\xeda-qu\xe9-implicancias-tiene-pesar-tests-25-y-comentarios-5-refleja-esto-las-prioridades-correctas-seg\xfan-la-investigaci\xf3n-emp\xedrica-de-defectos-o-es-una-valoraci\xf3n-subjetiva-de-robert-c-martin",level:3},{value:"9. [Cuestionar] La clase lista 4 niveles de seniority (Junior, Semi-Senior, Senior, Tech Lead) con diferentes enfoques de evaluaci\xf3n. \xbfC\xf3mo se diferencian REALMENTE estos niveles en la industria seg\xfan matrices de competencias como las de &quot;Engineering Ladders&quot; (progression.fyi, Dropbox, Square)? \xbfEn qu\xe9 dimensi\xf3n Clean Code diferencia niveles que la industria NO valora?",id:"9-cuestionar-la-clase-lista-4-niveles-de-seniority-junior-semi-senior-senior-tech-lead-con-diferentes-enfoques-de-evaluaci\xf3n-c\xf3mo-se-diferencian-realmente-estos-niveles-en-la-industria-seg\xfan-matrices-de-competencias-como-las-de-engineering-ladders-progressionfyi-dropbox-square-en-qu\xe9-dimensi\xf3n-clean-code-diferencia-niveles-que-la-industria-no-valora",level:3},{value:"10. [Cuestionar] La clase presenta Clean Code como un conjunto de pr\xe1cticas a aplicar y evaluar. \xbfQu\xe9 argumenta el movimiento &quot;Post-Clean Code&quot; representado por autores como Casey Muratori (&quot;Clean Code, Horrible Performance&quot;) o el art\xedculo &quot;Goodbye, Clean Code&quot; de Dan Abramov? \xbfCu\xe1l es la cr\xedtica central sobre el costo en PERFORMANCE de algunas pr\xe1cticas de Clean Code?",id:"10-cuestionar-la-clase-presenta-clean-code-como-un-conjunto-de-pr\xe1cticas-a-aplicar-y-evaluar-qu\xe9-argumenta-el-movimiento-post-clean-code-representado-por-autores-como-casey-muratori-clean-code-horrible-performance-o-el-art\xedculo-goodbye-clean-code-de-dan-abramov-cu\xe1l-es-la-cr\xedtica-central-sobre-el-costo-en-performance-de-algunas-pr\xe1cticas-de-clean-code",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-crap-index-change-risk-analysis-and-predictions-y-por-qu\xe9-combina-complejidad-ciclom\xe1tica-con-cobertura-de-tests-por-qu\xe9-es-una-m\xe9trica-m\xe1s-predictiva-de-riesgo-de-cambio-que-la-complejidad-ciclom\xe1tica-sola",children:'2. [Investigar] \xbfQu\xe9 es el "CRAP Index" (Change Risk Analysis and Predictions) y por qu\xe9 combina complejidad ciclom\xe1tica con cobertura de tests? \xbfPor qu\xe9 es una m\xe9trica m\xe1s predictiva de riesgo de cambio que la complejidad ciclom\xe1tica sola?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": El CRAP Index (Alberto Savoia, 2008, crap4j.org) combina complejidad ciclom\xe1tica (CC) y cobertura de tests (Coverage) en una f\xf3rmula: ",(0,i.jsx)(a.code,{children:"CRAP(m) = comp(m)^2 * (1 - cov(m)/100)^3 + comp(m)"}),". Un m\xe9todo con CC=1 y 100% de cobertura tiene CRAP=0 (riesgo nulo). Un m\xe9todo con CC=10 y 50% de cobertura tiene CRAP=10^2 * (1-0.5)^3 + 10 = 100 * 0.125 + 10 = 22.5 (riesgo alto). La intuici\xf3n: (a) un m\xe9todo complejo PERO con buena cobertura puede ser mantenible (los tests documentan su comportamiento), (b) un m\xe9todo simple SIN tests es riesgoso (nadie verific\xf3 que hace lo correcto), (c) un m\xe9todo complejo SIN tests es una bomba de tiempo. La complejidad ciclom\xe1tica sola ignora los tests; la cobertura sola ignora la complejidad. CRAP indexa AMBAS y predice mejor la probabilidad de introducir bugs al modificar. La clase pide cobertura >80% pero no la pondera por complejidad; CRAP index prioriza d\xf3nde escribir tests: m\xe9todos con CRAP > 30 merecen tests YA, aunque la cobertura global sea >80%."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase usa m\xe9tricas aisladas (cobertura, complejidad no mencionada). El CRAP index integra ambas y provee un ranking accionable. En el proyecto final, medir CRAP por m\xe9todo permite al alumno enfocar esfuerzos donde m\xe1s se necesita."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-el-rewrite-trap-del-que-advierte-joel-spolsky-y-por-qu\xe9-es-relevante-para-el-proyecto-final-de-refactorizaci\xf3n-qu\xe9-argumenta-spolsky-que-es-preferible-a-reescribir-un-sistema-legacy",children:'3. [Investigar] \xbfQu\xe9 es el "rewrite trap" del que advierte Joel Spolsky y por qu\xe9 es relevante para el proyecto final de refactorizaci\xf3n? \xbfQu\xe9 argumenta Spolsky que es preferible a reescribir un sistema legacy?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Joel Spolsky, en su art\xedculo "Things You Should Never Do, Part I" (2000, joelonsoftware.com), acu\xf1\xf3 el "rewrite trap" (la trampa de reescribir): la tentaci\xf3n de decir "este c\xf3digo es un desastre, reescrib\xe1moslo desde cero". Spolsky argumenta que reescribir es casi SIEMPRE una mala decisi\xf3n porque: (a) el c\xf3digo legacy contiene a\xf1os de conocimiento acumulado (bug fixes, casos borde, reglas de negocio impl\xedcitas que nadie document\xf3), (b) la reescritura tira TODO ese conocimiento a la basura y el nuevo sistema tarda a\xf1os en alcanzar la paridad funcional mientras acumula sus propios bugs, (c) ejemplos hist\xf3ricos: Netscape reescribi\xf3 su navegador y perdi\xf3 el mercado ante Microsoft. Lo que Spolsky recomienda es REFACTORIZACI\xd3N INCREMENTAL: mejorar el c\xf3digo pieza por pieza mientras sigue funcionando. Esto es EXACTAMENTE lo que el proyecto final pide hacer, pero la clase no cita a Spolsky ni advierte sobre la psicolog\xeda del "rewrite impulse" que los alumnos pueden sentir al ver el c\xf3digo legacy. El alumno debe reconocer la tentaci\xf3n de "borro todo y empiezo de nuevo" y resistirla con argumentos informados.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase pide refactorizar un sistema legacy sin explicar POR QU\xc9 refactorizar es superior a reescribir. Spolsky es la referencia cl\xe1sica sobre este tema y su art\xedculo es lectura obligatoria para cualquier ingeniero que toque c\xf3digo legacy. El alumno debe poder defender la estrategia de refactorizaci\xf3n con el argumento de Spolsky: el c\xf3digo legacy ES conocimiento corporativo materializado."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-el-bus-factor-o-lottery-factor-y-c\xf3mo-las-pr\xe1cticas-de-clean-code-lo-mitigan-qu\xe9-estudios-cuantitativos-existen-sobre-la-relaci\xf3n-entre-legibilidad-de-c\xf3digo-y-la-capacidad-de-incorporar-nuevos-desarrolladores-al-equipo",children:'4. [Investigar] \xbfQu\xe9 es el "Bus Factor" (o "Lottery Factor") y c\xf3mo las pr\xe1cticas de Clean Code lo mitigan? \xbfQu\xe9 estudios cuantitativos existen sobre la relaci\xf3n entre legibilidad de c\xf3digo y la capacidad de incorporar nuevos desarrolladores al equipo?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': El "Bus Factor" (o "Lottery Factor") es el n\xfamero m\xednimo de miembros del equipo que, si desaparecieran (atropellados por un bus, metaf\xf3ricamente), har\xedan que el proyecto no pudiera continuar porque el conocimiento est\xe1 concentrado en ellos. Clean Code mitiga el Bus Factor al hacer el conocimiento EXPL\xcdCITO en el c\xf3digo: si las variables tienen nombres significativos, las funciones son peque\xf1as y autoexplicativas, y los tests documentan el comportamiento esperado, un desarrollador nuevo puede entender el sistema sin depender del "experto que sabe c\xf3mo funciona". El estudio de Schwanke et al. (2013, Microsoft Research, "Measuring Architecture Quality by Structure Plus History Analysis") encontr\xf3 que equipos con c\xf3digo de alta legibilidad (medido por m\xe9tricas de Buse & Weimer) incorporan nuevos desarrolladores en promedio 40% m\xe1s r\xe1pido que equipos con baja legibilidad. El estudio tambi\xe9n encontr\xf3 que el Bus Factor bajo (conocimiento concentrado) es el mayor predictor de failure en proyectos de larga duraci\xf3n \u2014m\xe1s que la complejidad t\xe9cnica.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase presenta Clean Code como mejora t\xe9cnica individual. El Bus Factor revela que es una pr\xe1ctica de GESTI\xd3N DE RIESGO EMPRESARIAL: escribir c\xf3digo limpio no es un lujo del desarrollador, es proteger la inversi\xf3n de la empresa contra la p\xe9rdida de personal clave. Esta perspectiva es lo que convence a CTOs y stakeholders, y el alumno debe poder articularla."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"5-conectar-la-clase-presenta-una-r\xfabrica-de-evaluaci\xf3n-con-categor\xedas-nombres-funciones-tests-etc-c\xf3mo-se-relaciona-esta-r\xfabrica-con-los-niveles-de-software-maintainability-index-mi-definidos-en-el-est\xe1ndar-isoiec-25010-qu\xe9-mide-el-mi-que-la-r\xfabrica-de-la-clase-no-captura",children:'5. [Conectar] La clase presenta una r\xfabrica de evaluaci\xf3n con categor\xedas (Nombres, Funciones, Tests, etc.). \xbfC\xf3mo se relaciona esta r\xfabrica con los niveles de "Software Maintainability Index" (MI) definidos en el est\xe1ndar ISO/IEC 25010? \xbfQu\xe9 mide el MI que la r\xfabrica de la clase no captura?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': ISO/IEC 25010 (2011, "Systems and software Quality Requirements and Evaluation - SQuaRE") define la mantenibilidad como una caracter\xedstica de calidad compuesta por: modularidad, reusabilidad, analizabilidad, modificabilidad y testeabilidad. El Maintainability Index (MI) es una m\xe9trica compuesta que integra: l\xedneas de c\xf3digo, complejidad ciclom\xe1tica, volumen de Halstead (operadores/operandos), y porcentaje de l\xedneas de comentario. La f\xf3rmula produce un score 0-100 (donde > 85 es "alta mantenibilidad"). La r\xfabrica de la clase es cualitativa y subjetiva ("revelan intenci\xf3n", "varios confusos"); el MI es cuantitativo y automatizable. Lo que el MI captura que la r\xfabrica no: (a) volumen de Halstead (densidad de operadores que predice esfuerzo de comprensi\xf3n), (b) proporci\xf3n de comentarios como m\xe9trica objetiva (no opini\xf3n sobre si son "buenos"), (c) tracking en el tiempo (MI puede monitorearse build a build para detectar tendencias negativas antes de que lleguen a ser "insuficientes" en la r\xfabrica). La r\xfabrica captura aspectos cualitativos (revelar intenci\xf3n en nombres) que el MI no mide.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase usa una r\xfabrica subjetiva. El MI es un est\xe1ndar internacional que complementa la evaluaci\xf3n cualitativa con medici\xf3n continua automatizada. El alumno debe entender que en la industria se usan AMBOS: r\xfabricas humanas (code review) + m\xe9tricas autom\xe1ticas (MI, complejidad). ISO 25010 es el est\xe1ndar de calidad de software que referencia cualquier proceso formal."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"6-conectar-la-clase-estructura-la-entrevista-t\xe9cnica-con-10-ejercicios-pr\xe1cticos-y-50-preguntas-te\xf3ricas-qu\xe9-es-el-m\xe9todo-star-situation-task-action-result-para-entrevistas-de-comportamiento-y-c\xf3mo-se-aplica-para-responder-preguntas-sobre-experiencia-con-clean-code-que-van-m\xe1s-all\xe1-de-las-respuestas-t\xe9cnicas",children:"6. [Conectar] La clase estructura la entrevista t\xe9cnica con 10 ejercicios pr\xe1cticos y 50 preguntas te\xf3ricas. \xbfQu\xe9 es el m\xe9todo STAR (Situation, Task, Action, Result) para entrevistas de comportamiento y c\xf3mo se aplica para responder preguntas sobre experiencia con Clean Code que van m\xe1s all\xe1 de las respuestas t\xe9cnicas?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': El m\xe9todo STAR es un marco para estructurar respuestas en entrevistas de comportamiento (behavioral interviews): Situation (contexto: "En el proyecto de payroll, ten\xedamos un endpoint de c\xe1lculo que tardaba 30 segundos"), Task (mi responsabilidad: "Me asignaron optimizarlo refactorizando el c\xf3digo legacy"), Action (qu\xe9 hice espec\xedficamente: "Apliqu\xe9 extracci\xf3n de m\xe9todos hasta reducirlos a <20 l\xedneas, elimin\xe9 3 queries duplicadas usando DRY, encapsul\xe9 c\xe1lculos en Value Objects con invariantes de negocio, escrib\xed 45 characterization tests antes de tocar l\xf3gica"), Result (resultados medibles: "El endpoint baj\xf3 a 1.2 segundos, la cobertura de tests subi\xf3 de 12% a 85%, y 0 bugs en producci\xf3n en 6 meses"). La clase prepara al alumno para respuestas T\xc9CNICAS directas ("\xbfqu\xe9 es SRP?"), pero en entrevistas reales, los entrevistadores preguntan "contame de una vez que aplicaste Clean Code" y eval\xfaan profundidad de experiencia a trav\xe9s de STAR. Sin estructura STAR, el alumno responde con generalidades ("s\xed, siempre nombro bien las variables") que no demuestran experiencia real.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase es puramente t\xe9cnica. El m\xe9todo STAR es el est\xe1ndar de la industria para entrevistas de comportamiento (usado en Amazon, Google, Meta para todos los niveles). El alumno que integra conocimiento t\xe9cnico con estructura STAR es mucho m\xe1s efectivo en entrevistas."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"7-conectar-la-clase-pide-cobertura--80-como-requisito-del-proyecto-final-qu\xe9-dice-la-investigaci\xf3n-de-inozemtseva-y-holmes-2014-icse-sobre-la-correlaci\xf3n-entre-cobertura-de-tests-y-defectos-post-release-por-qu\xe9-coverage-is-not-a-good-measure-of-test-suite-quality-seg\xfan-este-estudio",children:'7. [Conectar] La clase pide cobertura > 80% como requisito del proyecto final. \xbfQu\xe9 dice la investigaci\xf3n de Inozemtseva y Holmes (2014, ICSE) sobre la correlaci\xf3n entre cobertura de tests y defectos post-release? \xbfPor qu\xe9 "coverage is not a good measure of test suite quality" seg\xfan este estudio?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Laura Inozemtseva y Reid Holmes (University of Waterloo, ICSE 2014, "Coverage Is Not Strongly Correlated with Test Suite Effectiveness") analizaron 5 proyectos open-source grandes (Eclipse, Tomcat, etc.) con m\xe1s de 100 millones de l\xedneas de c\xf3digo combinadas. Conclusi\xf3n principal: la cobertura (line/branch coverage) tiene una CORRELACI\xd3N BAJA (r \u2248 0.2-0.3) con la efectividad real de los tests para detectar defectos. Los factores que S\xcd correlacionan fuertemente: (a) la diversidad de datos de entrada en los tests (inputs variados), (b) el tama\xf1o del suite de tests (n\xfamero de tests, no l\xedneas cubiertas), (c) la madurez del proyecto (proyectos m\xe1s viejos con m\xe1s tests tienden a tener menos bugs independientemente del % de cobertura). El estudio encontr\xf3 que la cobertura es un proxy D\xc9BIL: un suite con 90% de cobertura generada por tests sin asserts es peor que un suite con 50% de cobertura con tests que verifican comportamiento. La implicancia: la clase pide >80% de cobertura como meta, pero esta meta es insuficiente (y potencialmente enga\xf1osa) sin verificar la CALIDAD de los tests a trav\xe9s de mutation testing o code review de tests.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase usa cobertura como m\xe9trica principal de calidad de tests. El estudio de Inozemtseva & Holmes es la investigaci\xf3n m\xe1s citada sobre las limitaciones de coverage. La conclusi\xf3n: 80% es un m\xednimo necesario pero NO suficiente. El alumno debe entender que cobertura alta con tests malos es falsa seguridad."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"8-cuestionar-la-clase-eval\xfaa-el-proyecto-con-una-r\xfabrica-que-asigna-pesos-a-cada-categor\xeda-qu\xe9-implicancias-tiene-pesar-tests-25-y-comentarios-5-refleja-esto-las-prioridades-correctas-seg\xfan-la-investigaci\xf3n-emp\xedrica-de-defectos-o-es-una-valoraci\xf3n-subjetiva-de-robert-c-martin",children:"8. [Cuestionar] La clase eval\xfaa el proyecto con una r\xfabrica que asigna pesos a cada categor\xeda. \xbfQu\xe9 implicancias tiene pesar Tests 25% y Comentarios 5%? \xbfRefleja esto las prioridades correctas seg\xfan la investigaci\xf3n emp\xedrica de defectos, o es una valoraci\xf3n subjetiva de Robert C. Martin?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Los pesos de la r\xfabrica (Tests 25%, Funciones 15%, Errores 15%, Clases 15%, Nombres 10%, Adapters 10%, Comentarios 5%, Formato 5%) reflejan las prioridades SUBJETIVAS del dise\xf1o del curso. La pregunta es si la evidencia emp\xedrica las respalda: (a) Tests pesa 25% \u2192 consistente con la investigaci\xf3n: los estudios muestran que la presencia de una suite de tests robusta es el factor #1 en reducci\xf3n de defectos (m\xe1s predictivo que cualquier m\xe9trica de c\xf3digo), (b) Nombres pesa 10% \u2192 probablemente SUB-ponderado: el estudio de Buse & Weimer (2012) muestra que identificadores confusos son el principal factor que frena la legibilidad; Arnaoudova et al. encontraron que "linguistic anti-patterns" en nombres son predictores de bugs tan fuertes como la complejidad, (c) Comentarios pesa 5% \u2192 razonable porque Clean Code argumenta que buen c\xf3digo reduce la necesidad de comentarios, pero el estudio de Ibrahim et al. muestra que comentarios Javadoc en APIs p\xfablicas aportan valor medible, (d) Formato pesa 5% \u2192 subestimado: la consistencia de formato afecta la velocidad de lectura (Busjahn et al., eye-tracking), pero automatizar el formato con Spotless hace que el peso en la NOTA sea bajo porque se corrige solo. Una r\xfabrica mejor podr\xeda pesar Nombres m\xe1s alto (15%) y reducir el peso combinado de Comentarios+Formato dado que las herramientas los automatizan.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La r\xfabrica se presenta como objetiva, pero sus pesos son decisiones editoriales de Martin. El alumno debe desarrollar pensamiento cr\xedtico sobre las METODOLOG\xcdAS de evaluaci\xf3n que usar\xe1 en su carrera, incluyendo cuestionar si los pesos asignados reflejan evidencia emp\xedrica o intuici\xf3n del autor."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"9-cuestionar-la-clase-lista-4-niveles-de-seniority-junior-semi-senior-senior-tech-lead-con-diferentes-enfoques-de-evaluaci\xf3n-c\xf3mo-se-diferencian-realmente-estos-niveles-en-la-industria-seg\xfan-matrices-de-competencias-como-las-de-engineering-ladders-progressionfyi-dropbox-square-en-qu\xe9-dimensi\xf3n-clean-code-diferencia-niveles-que-la-industria-no-valora",children:'9. [Cuestionar] La clase lista 4 niveles de seniority (Junior, Semi-Senior, Senior, Tech Lead) con diferentes enfoques de evaluaci\xf3n. \xbfC\xf3mo se diferencian REALMENTE estos niveles en la industria seg\xfan matrices de competencias como las de "Engineering Ladders" (progression.fyi, Dropbox, Square)? \xbfEn qu\xe9 dimensi\xf3n Clean Code diferencia niveles que la industria NO valora?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Matrices como progression.fyi (recopilaci\xf3n de ladders de 50+ empresas) y las de Dropbox/Spotify/Square definen niveles de seniority en 4 ejes: (a) Impacto (alcance del trabajo: componente \u2192 sistema \u2192 m\xfaltiples sistemas \u2192 organizaci\xf3n), (b) Autonom\xeda (necesita gu\xeda \u2192 independiente \u2192 gu\xeda a otros \u2192 define direcci\xf3n), (c) Complejidad (tareas definidas \u2192 problemas ambiguos \u2192 define problemas \u2192 define estrategia), (d) Influencia (individual \u2192 equipo \u2192 m\xfaltiples equipos \u2192 industria). La r\xfabrica de la clase eval\xfaa CALIDAD DE C\xd3DIGO (aplicar reglas \u2192 refactorizar \u2192 patrones \u2192 est\xe1ndares), lo cual se alinea con el eje de Impacto pero ignora que la industria valora MUCHO m\xe1s el eje de Influencia (mentoring, code reviews, dise\xf1o de procesos de equipo) en niveles altos. Un Senior que escribe c\xf3digo perfecto pero no mentorea juniors ser\xe1 evaluado como Semi-Senior en la mayor\xeda de las empresas. La clase deja la impresi\xf3n de que "aplicar m\xe1s principios" = mayor seniority; la industria eval\xfaa seniority por el radio de impacto y la capacidad de elevar al equipo.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase conceptualiza seniority exclusivamente como dominio t\xe9cnico de Clean Code. En la industria, un Senior es evaluado por la capacidad de hacer al EQUIPO m\xe1s efectivo, no solo por escribir mejor c\xf3digo. El alumno debe entender esta diferencia para no sobredimensionar su nivel real basado solo en conocimiento t\xe9cnico."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"10-cuestionar-la-clase-presenta-clean-code-como-un-conjunto-de-pr\xe1cticas-a-aplicar-y-evaluar-qu\xe9-argumenta-el-movimiento-post-clean-code-representado-por-autores-como-casey-muratori-clean-code-horrible-performance-o-el-art\xedculo-goodbye-clean-code-de-dan-abramov-cu\xe1l-es-la-cr\xedtica-central-sobre-el-costo-en-performance-de-algunas-pr\xe1cticas-de-clean-code",children:'10. [Cuestionar] La clase presenta Clean Code como un conjunto de pr\xe1cticas a aplicar y evaluar. \xbfQu\xe9 argumenta el movimiento "Post-Clean Code" representado por autores como Casey Muratori ("Clean Code, Horrible Performance") o el art\xedculo "Goodbye, Clean Code" de Dan Abramov? \xbfCu\xe1l es la cr\xedtica central sobre el costo en PERFORMANCE de algunas pr\xe1cticas de Clean Code?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Casey Muratori, en su charla "Clean Code, Horrible Performance" (2023), argumenta que varias pr\xe1cticas de Clean Code tienen un COSTO DE PERFORMANCE significativo que el libro ignora: (a) funciones peque\xf1as \u2192 cada llamada a funci\xf3n tiene overhead de stack frame, branch prediction y cache locality: en un loop de 10M de iteraciones, extraer el cuerpo a una funci\xf3n puede multiplicar x3 el tiempo de ejecuci\xf3n, (b) polimorfismo sobre switch \u2192 despacho virtual (vtable) es m\xe1s lento que una tabla de saltos (switch), y en hot paths la diferencia es medible, (c) objetos peque\xf1os con getters/setters \u2192 fragmentation de memoria (muchos objetos en heap en lugar de arrays contiguos) destruye la cache locality que CPUs modernas necesitan. Dan Abramov (creador de Redux, React core team) escribi\xf3 "Goodbye, Clean Code" (2020) argumentando que la b\xfasqueda de "c\xf3digo limpio" puede llevar a abstracciones innecesarias que oscurecen m\xe1s de lo que revelan, citando ejemplos donde \xe9l mismo introdujo complejidad por seguir principios de Clean Code. La cr\xedtica no es "Clean Code es malo" sino "Clean Code optimiza para legibilidad humana y asume que la performance no importa \u2014lo cual es cierto en CRUDs pero falso en sistemas de alto rendimiento, motores de juegos, o procesamiento de datos masivo".']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase no menciona trade-offs de performance. Muratori (Handmade Hero, ex-RAD Game Tools) y Abramov (React) representan comunidades donde la performance importa. El alumno debe entender que Clean Code es \xf3ptimo para la mayor\xeda del software empresarial pero tiene contraindicaciones en dominios espec\xedficos. Un profesional maduro elige cu\xe1ndo aplicar cada principio basado en los requerimientos del dominio, no aplica Clean Code como receta universal."]})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>n,x:()=>t});var s=o(96540);const i={},r=s.createContext(i);function n(e){const a=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:n(e.components),s.createElement(r.Provider,{value:a},e.children)}}}]);